// Lê o aviso do Evolution API e descarta o que não é mensagem nova de uma pessoa.
const esperado = $env.WEBHOOK_TOKEN;
const saida = [];
for (const item of $input.all()) {
  const headers = item.json.headers || {};
  if (!esperado || headers['x-webhook-token'] !== esperado) continue; // não veio do nosso Evolution
  const b = item.json.body || {};
  if (b.event !== 'messages.upsert') continue;
  const d = Array.isArray(b.data) ? b.data[0] : b.data;
  const k = (d && d.key) || {};
  if (k.fromMe) continue; // mensagens enviadas pela própria agência
  let jid = k.remoteJid || '';
  if (jid.endsWith('@lid')) jid = k.remoteJidAlt || k.senderPn || '';
  if (!jid.endsWith('@s.whatsapp.net')) continue; // grupos, status e canais
  const m = d.message || {};
  const texto = m.conversation || (m.extendedTextMessage && m.extendedTextMessage.text)
    || (m.imageMessage && m.imageMessage.caption) || (m.videoMessage && m.videoMessage.caption)
    || '[' + (d.messageType || 'mensagem') + ']';
  saida.push({ json: { instancia: b.instance, numero: jid.split('@')[0], nome: d.pushName || '', mensagem: texto } });
}
return saida;

// Só responde automaticamente no primeiro contato.
const padrao = 'Olá, {nome}! 👋 Aqui é da Maragogi Lab. Recebemos sua mensagem e já já alguém da equipe te responde.\n\nPra adiantar: você procura vídeo/fotografia, gestão de redes sociais ou tráfego pago?';
const modelo = $env.MENSAGEM_BOAS_VINDAS || padrao;
const contatos = $('Ler mensagem').all();
return $input.all().map((item, i) => ({ item, contato: contatos[i].json }))
  .filter(({ item }) => item.json.novo === true)
  .map(({ contato }) => ({ json: {
    instancia: contato.instancia,
    numero: contato.numero,
    texto: modelo.replace(/\{nome\}/g, (contato.nome || '').split(' ')[0] || 'tudo bem'),
  } }));
